import bpy
exec("
fixed=[]
for o in C.objects:
    if o.type!='MESH':continue
    if any(k in o.name for k in ['RoofTile','RoofUnderlay','TradeCanopy','AwningCanvas','EntryEarthPath','WorkingApron','SchoolPennant']):
        bm=bmesh.new();bm.from_mesh(o.data)
        if 'SchoolPennant' not in o.name:
            faces=[f for f in bm.faces if f.normal.z<0]
            if faces:bmesh.ops.reverse_faces(bm,faces=faces);fixed.append(o.name)
        bm.to_mesh(o.data);bm.free()
# Slightly ragged boundaries and a vertex-alpha feather ground the earthen approaches.
for o in C.objects:
    if o.name.startswith(('Town_EntryEarthPath','Town_WorkingApron')):
        if o.name.startswith('Town_WorkingApron'):
            # Irregular edge follows local ground instead of creating a rectangular mat.
            for v in o.data.vertices:
                row=v.index//9;col=v.index%9
                if row in [0,5] or col in [0,8]:
                    v.co.x+=.06*math.sin(v.index*2.7);v.co.y+=.10*math.sin(v.index*1.7)
                    gz=-v.co.y;v.co.z=height(v.co.x-shore(gz),gz)+.019
        o['town_path']=True
# Add discreet service doorsills on rear facades that sink into the bank; keep ground shape.
(LOG/'roof_orientation_fix.json').write_text(json.dumps(fixed,indent=2),encoding='utf8')
bpy.context.view_layer.update();bpy.ops.wm.save_as_mainfile(filepath=str(ROOT/'source/reference_harbor_mcp.blend'))
export_collection('Reference_Town','town.glb')
bpy.ops.wm.save_as_mainfile(filepath=str(ROOT/'source/reference_harbor_mcp.blend'))
